
begin;
create table sim_murid_private.survey_questions(role text not null,code text not null,kind text not null check(kind in('likert','essay')),question text not null,section text not null,aspect text not null,required boolean not null,attention integer,ordinal integer not null,primary key(role,code));
create table sim_murid_private.survey_periods(id uuid primary key default gen_random_uuid(),title text not null,academic_year_id uuid not null references public.academic_years(id),semester integer not null check(semester in(1,2)),starts_on date not null,ends_on date not null,status text not null default 'open' check(status in('open','closed')),targets text[] not null,kind text not null default 'main' check(kind in('main','micro')),questions jsonb,exam_override text,instrument_version text not null default 'SURVEI-1.0',created_by uuid not null references public.profiles(id),check(ends_on>=starts_on));
create index survey_period_year on sim_murid_private.survey_periods(academic_year_id);
create index survey_period_actor on sim_murid_private.survey_periods(created_by);
create table sim_murid_private.survey_respondents(period_id uuid references sim_murid_private.survey_periods(id),user_id uuid references public.profiles(id),role text not null,rotation text[] not null default '{}',peers uuid[] not null default '{}',instrument jsonb not null,revision bigint not null default 0,answers jsonb not null default '{}',peer_answers jsonb not null default '{}',peer_submitted_at timestamptz,submitted_at timestamptz,flags jsonb,admin_note text,started_at timestamptz not null default now(),primary key(period_id,user_id));
create index survey_respondent_user on sim_murid_private.survey_respondents(user_id);
create function public.app_survey_manager(p_actor uuid,p_session uuid) returns boolean language sql stable security invoker set search_path='' as $$select public.app_onboarding_ready(p_actor,p_session) and(public.app_education_admin(p_actor,p_session) or public.app_education_task(p_actor,'school_head'))$$;
create function public.app_survey_open(p_period uuid) returns boolean language sql stable security invoker set search_path='' as $$select exists(select 1 from sim_murid_private.survey_periods where id=p_period and status='open' and public.app_ops_today() between starts_on and ends_on)$$;
create function public.app_survey_start(p_actor uuid,p_session uuid,p_period uuid) returns jsonb language plpgsql security invoker set search_path='' as $$
#variable_conflict use_variable
declare p sim_murid_private.survey_periods%rowtype;r sim_murid_private.survey_respondents%rowtype;role text;rotation text[]:='{}';peers uuid[]:='{}';instrument jsonb;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 select * into p from sim_murid_private.survey_periods where id=p_period;if not found then return jsonb_build_object('code','not_found');end if;
 select * into r from sim_murid_private.survey_respondents where period_id=p_period and user_id=p_actor;if found then return jsonb_build_object('code','saved','response',to_jsonb(r));end if;
 select role_code into role from public.user_roles where user_id=p_actor;
 if not public.app_survey_open(p_period) or not role=any(p.targets) then return jsonb_build_object('code','denied');end if;
 perform 1 from sim_murid_private.operations_state for update;
 if p.kind='main' and role='student' then
 select array_agg(code order by frequency,jitter) into rotation from(select code,(select count(*) from sim_murid_private.survey_respondents hist where hist.user_id=p_actor and code=any(hist.rotation))frequency,md5(p_actor::text||p_period::text||code)jitter from unnest(array['AQH','AKA','FIK','SKI','BAR','PPC','BIN','MTK','IPA','IPS','BIG','INF','PJK','SBD','BTQ'])code order by frequency,jitter limit 8)x;
 end if;
 if p.kind='main' and role='teacher' then select coalesce(array_agg(id),'{}') into peers from(select prof.id from public.profiles prof join public.user_roles ur on ur.user_id=prof.id where ur.role_code='teacher' and prof.status='active' and prof.id<>p_actor order by md5(prof.id::text||p_actor::text||p_period::text) limit 12)x;end if;
 if p.kind='micro' then instrument=p.questions;else select jsonb_agg(to_jsonb(q) order by ordinal) into instrument from sim_murid_private.survey_questions q where q.role=role and(q.section<>'C' or q.aspect='ATT' or q.aspect=any(rotation));end if;
 select * into r from sim_murid_private.survey_respondents where period_id=p_period and user_id=p_actor;return jsonb_build_object('code','saved','response',to_jsonb(r));end$$;
create function public.app_survey_flags(p_instrument jsonb,p_answers jsonb,p_seconds numeric,p_role text) returns jsonb language plpgsql immutable security invoker set search_path='' as $$
#variable_conflict use_variable
declare straight boolean;short boolean;attention integer;active integer;begin
 select count(*)>=20 and count(distinct(p_answers->> (q->>'code')))=1 into straight from jsonb_array_elements(p_instrument)q where q->>'kind'='likert' and q->>'attention' is null;
 select count(*)::integer into attention from jsonb_array_elements(p_instrument)q where q->>'attention' is not null and(p_answers->>(q->>'code'))::integer is distinct from(q->>'attention')::integer;
 short=p_seconds<case when p_role='teacher' then 180 else 120 end;active=straight::integer+short::integer+(attention>=2)::integer;
 return jsonb_build_object('straightline',straight,'short',short,'attention',case when attention=0 then 'aman' when attention=1 then 'peringatan' else 'tidak_valid' end,'reliability',case when active>=2 then 'rendah' when active=1 or attention=1 then 'sedang' else 'tinggi' end);end$$;
create function public.app_survey_mutate(p_actor uuid,p_session uuid,p_command jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
#variable_conflict use_variable
declare p sim_murid_private.survey_periods%rowtype;r sim_murid_private.survey_respondents%rowtype;id uuid;item jsonb;q jsonb;answers jsonb;peer uuid;missing jsonb:='[]';v jsonb;begin
 if not public.app_onboarding_ready(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 id=(p_command->>'periodId')::uuid;
 if p_command->>'type'='period' then
 if not public.app_survey_manager(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 if exists(select 1 from public.holidays where holiday_date between(p_command->>'start')::date and(p_command->>'start')::date+13 and description~*'(ujian|asesmen|ATS|ASAS|PTS|PAS)') and length(btrim(coalesce(p_command->>'examOverride','')))<3 then return jsonb_build_object('code','exam_warning');end if;
 if id is not null and exists(select 1 from sim_murid_private.survey_respondents where period_id=id) then return jsonb_build_object('code','locked');end if;
 if id is null then insert into sim_murid_private.survey_periods(title,academic_year_id,semester,starts_on,ends_on,targets,kind,questions,exam_override,created_by) values(p_command->>'title',(p_command->>'yearId')::uuid,(p_command->>'semester')::integer,(p_command->>'start')::date,(p_command->>'end')::date,array(select jsonb_array_elements_text(p_command->'targets')),p_command->>'kind',p_command->'questions',p_command->>'examOverride',p_actor) returning survey_periods.id into id;
 else update sim_murid_private.survey_periods set title=p_command->>'title',starts_on=(p_command->>'start')::date,ends_on=(p_command->>'end')::date,targets=array(select jsonb_array_elements_text(p_command->'targets')),exam_override=p_command->>'examOverride' where survey_periods.id=id;end if;return jsonb_build_object('code','saved','id',id);
 elsif p_command->>'type'='close' then
 if not public.app_survey_manager(p_actor,p_session) then return jsonb_build_object('code','denied');end if;
 update sim_murid_private.survey_periods set status='closed' where survey_periods.id=id;return jsonb_build_object('code','saved','id',id);
 elsif p_command->>'type'='start' then return public.app_survey_start(p_actor,p_session,id);
 end if;
 select * into p from sim_murid_private.survey_periods where survey_periods.id=id;
 select * into r from sim_murid_private.survey_respondents where period_id=id and user_id=p_actor for update;
 if not found or not public.app_survey_open(id) or r.submitted_at is not null then return jsonb_build_object('code','locked');end if;
 if r.revision is distinct from(p_command->>'version')::bigint then return jsonb_build_object('code','stale');end if;
 if p_command->>'type' in('save','submit') then
 answers=p_command->'answers';if jsonb_typeof(answers)<>'object' then return jsonb_build_object('code','invalid');end if;
 for item in select to_jsonb(x) from jsonb_each(answers)x loop
 select value into q from jsonb_array_elements(r.instrument) where value->>'code'=item->>'key';if not found then return jsonb_build_object('code','invalid');end if;
 v=item->'value';if q->>'kind'='likert' and(jsonb_typeof(v)<>'number' or(v#>>'{}')::numeric not between 1 and 5 or(v#>>'{}')::numeric<>trunc((v#>>'{}')::numeric)) then return jsonb_build_object('code','invalid');end if;
 if q->>'kind'='essay' and(jsonb_typeof(v)<>'string' or length(v#>>'{}')>10000) then return jsonb_build_object('code','invalid');end if;
 end loop;
 if p_command->>'type'='submit' then
 for q in select value from jsonb_array_elements(r.instrument) loop if coalesce((q->>'required')::boolean,true) and (answers->>(q->>'code') is null or btrim(answers->>(q->>'code'))='') then missing=missing||jsonb_build_array(q->>'code');end if;end loop;
 if jsonb_array_length(missing)>0 then return jsonb_build_object('code','incomplete','missing',missing);end if;
 if r.role='teacher' and p.kind='main' and cardinality(r.peers)>0 and r.peer_submitted_at is null then return jsonb_build_object('code','peer_incomplete');end if;
 end if;
 update sim_murid_private.survey_respondents set answers=answers,revision=revision+1,submitted_at=case when p_command->>'type'='submit' then now() else null end,flags=case when p_command->>'type'='submit' then public.app_survey_flags(r.instrument,answers,extract(epoch from now()-r.started_at),r.role) else null end where period_id=id and user_id=p_actor;
 elsif p_command->>'type' in('peer_save','peer_submit') then
 if r.role<>'teacher' or p.kind<>'main' or r.peer_submitted_at is not null then return jsonb_build_object('code','denied');end if;
 answers=p_command->'answers';if jsonb_typeof(answers)<>'object' then return jsonb_build_object('code','invalid');end if;
 for item in select to_jsonb(x) from jsonb_each(answers)x loop peer=(item->>'key')::uuid;if not peer=any(r.peers) then return jsonb_build_object('code','denied');end if;
 for q in select value from jsonb_array_elements(jsonb_build_array(1,2,3,4,5,6)) loop v=item->'value'->('PTS-'||(q#>>'{}'));if v is not null and v<>'"TT"'::jsonb and(jsonb_typeof(v)<>'number' or(v#>>'{}')::numeric not between 1 and 5 or(v#>>'{}')::numeric<>trunc((v#>>'{}')::numeric)) then return jsonb_build_object('code','invalid');end if;end loop;
 if length(coalesce(item->'value'->>'PTS-7',''))>10000 then return jsonb_build_object('code','invalid');end if;end loop;
 if p_command->>'type'='peer_submit' then foreach peer in array r.peers loop for q in select value from jsonb_array_elements(jsonb_build_array(1,2,3,4,5,6)) loop if answers->peer::text->('PTS-'||(q#>>'{}')) is null then return jsonb_build_object('code','peer_incomplete');end if;end loop;end loop;end if;
 update sim_murid_private.survey_respondents set peer_answers=answers,revision=revision+1,peer_submitted_at=case when p_command->>'type'='peer_submit' then now() else null end where period_id=id and user_id=p_actor;
 else return jsonb_build_object('code','invalid');end if;
 return jsonb_build_object('code','saved','version',r.revision+1);end$$;
do $$declare t text;r record;begin foreach t in array array['survey_questions','survey_periods','survey_respondents'] loop execute format('alter table sim_murid_private.%I enable row level security',t);execute format('revoke all on sim_murid_private.%I from public,anon,authenticated',t);execute format('grant select,insert,update,delete on sim_murid_private.%I to service_role',t);end loop;for r in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'app_survey_%' loop execute format('revoke all on function %s from public,anon,authenticated',r.signature);execute format('grant execute on function %s to service_role',r.signature);end loop;end$$;

create function sim_murid_private.survey_lock() returns trigger language plpgsql security invoker set search_path='' as $$begin
 if tg_op='DELETE' then if old.submitted_at is not null or old.peer_submitted_at is not null then raise exception 'Submitted survey is immutable';end if;return old;end if;
 if old.submitted_at is not null and row(new.answers,new.instrument,new.rotation,new.peers,new.submitted_at,new.flags,new.started_at) is distinct from row(old.answers,old.instrument,old.rotation,old.peers,old.submitted_at,old.flags,old.started_at) then raise exception 'Submitted survey is immutable';end if;
 if old.peer_submitted_at is not null and row(new.peer_answers,new.peers,new.peer_submitted_at) is distinct from row(old.peer_answers,old.peers,old.peer_submitted_at) then raise exception 'Submitted peer assessment is immutable';end if;return new;end$$;
create trigger survey_final_lock before update or delete on sim_murid_private.survey_respondents for each row execute function sim_murid_private.survey_lock();
commit;
